contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2);
        uint before1 = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        c.addToBalance{value: amount1}(); if (__ESBMC_reverted()) return;
        uint mid = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        c.addToBalance{value: amount2}(); if (__ESBMC_reverted()) return;
        uint finalBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        assert(before1 == 0 && mid == before1 + amount1 && finalBal == mid + amount2);
    }
    receive() external payable {}
}

