// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        uint256 before1;
        try c.getBalance(address(this)) returns (uint256 __r) { before1 = __r; } catch { return; }
        try c.addToBalance{value: amount1}() {} catch { return; }
        uint256 mid;
        try c.getBalance(address(this)) returns (uint256 __r) { mid = __r; } catch { return; }
        try c.addToBalance{value: amount2}() {} catch { return; }
        uint256 finalBal;
        try c.getBalance(address(this)) returns (uint256 __r) { finalBal = __r; } catch { return; }
        assertTrue(before1 == 0 && mid == before1 + amount1 && finalBal == mid + amount2);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
